class Echo:
    LOCALE = 4
    def compile(self, pattern, flags=0): return pattern + ':' + str(flags)
re = Echo()
print(re.compile(r'\N{NOT A CHARACTER}', re.LOCALE))

class Echo:
    LOCALE = 4
    def search(self, pattern, text, flags=0): return text
def apply(re): return re.search(r'\N{NOT A CHARACTER}', 'ok', re.LOCALE)
print(apply(Echo()))
